def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_def = 0
    for a in op:
        if a == 'D':
            op_def += 1
    my_def = 0
    for a in my:
        if a == 'D':
            my_def += 1

    last_op = op[-1]
    last_me = my[-1]

    # Opponent never defected: keep the cooperation river flowing, exploit only at the very end.
    if op_def == 0:
        if n >= 99:
            return 'D'
        return 'C'

    # Opponent defects almost always: don't be a martyr.
    if op_def * 2 > n + 4:
        if n >= 99:
            return 'D'
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Detect a stuck mutual-defection loop and try to restart cooperation.
    dd_run = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'D' and op[i] == 'D':
            dd_run += 1
        else:
            break
    if dd_run >= 3:
        if n >= 98:
            return 'D'
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent just defected.
    if last_op == 'D':
        if n >= 98:
            return 'D'
        # Single isolated defection: retaliate once, then forgive to avoid a spiral.
        if op_def == 1 and n >= 2:
            if last_me == 'D':
                return 'C'
            return 'D'
        # A short burst of defections: punish, but test the waters periodically.
        streak = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                streak += 1
            else:
                break
        if streak >= 4:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if streak >= 2:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # Occasional forgiveness for a slightly defecting but mostly cooperative opponent.
        if op_def * 4 <= n and rng.random() < 0.4:
            return 'C'
        return 'D'

    # Opponent just cooperated.
    if n >= 99:
        return 'D'

    # If we've been the aggressor and opponent keeps cooperating, settle down.
    if my_def > op_def + 2:
        return 'C'

    # Late-game exploitation of a trusty cooperator: defect in the final stretch.
    if n >= 96:
        if op_def * 6 <= n:
            return 'D'
        return 'C'

    # Occasional probing of a very cooperative opponent, but rarely, to preserve trust.
    if op_def == 1:
        if n >= 20 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # Mostly cooperative opponent: cooperate, probe sparingly.
    if op_def * 4 <= n:
        if n >= 30 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Moderate defector: return to cooperation but stay ready to retaliate.
    if rng.random() < 0.1:
        return 'D'
    return 'C'
